1. Warm up on a page built to be scraped

library(rvest)
library(dplyr)
library(stringr)
library(readr)

books_pg &lt;- read_html(
  "https://books.toscrape.com/catalogue/page-1.html")

books &lt;- tibble(
  title = books_pg |&gt;
    html_elements("article.product_pod h3 a") |&gt;
    html_attr("title"),

  price = books_pg |&gt;
    html_elements("article.product_pod p.price_color") |&gt;
    html_text2(),

  rating = books_pg |&gt;
    html_elements("article.product_pod p.star-rating") |&gt;
    html_attr("class") |&gt;
    str_remove("star-rating ")
) |&gt;
  mutate(price_gbp = parse_number(price))

head(books)

# A tibble: 6 × 4
  title                                 price  rating price_gbp
  &lt;chr&gt;                                 &lt;chr&gt;  &lt;chr&gt;      &lt;dbl&gt;
1 A Light in the Attic                  £51.77 Three       51.8
2 Tipping the Velvet                    £53.74 One         53.7
3 Soumission                            £50.10 One         50.1
4 Sharp Objects                         £47.82 Four        47.8
5 Sapiens: A Brief History of Humankind £54.23 Five        54.2
6 The Requiem Red                       £22.65 One         22.7



books_5pages &lt;- books

for (i in 2:5) {
  books_pg &lt;- read_html(
    paste0(
      "https://books.toscrape.com/catalogue/page-",
      i,
      ".html"))

  books_page &lt;- tibble(
    title = books_pg |&gt;
      html_elements("article.product_pod h3 a") |&gt;
      html_attr("title"),

    price = books_pg |&gt;
      html_elements("article.product_pod p.price_color") |&gt;
      html_text2(),

    rating = books_pg |&gt;
      html_elements("article.product_pod p.star-rating") |&gt;
      html_attr("class") |&gt;
      str_remove("star-rating ")
  ) |&gt;
    mutate(price_gbp = parse_number(price))

  books_5pages &lt;- bind_rows(books_5pages, books_page)}

head(books_5pages)

